#define MAX_STEPS 100
#define  MAX_DIST 100.0
#define SURFACE_DIST 0.001
#define AA 2

// Dot 2
float dot2(in vec2 v) { return dot(v,v); }

// Rotation matrix around the X axis.
mat3 rotateX(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(1, 0, 0),
        vec3(0, c, s),
        vec3(0, -s, c)
    );
}

// Rotation matrix around the Y axis.
mat3 rotateY(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(c, 0, s),
        vec3(0, 1, 0),
        vec3(-s, 0, c)
    );
}

// Radial UV from https://www.shadertoy.com/view/XdXXzf
vec2 radialUV(in vec2 uv)
{
    vec2 rUV = vec2(0.0);
    rUV.x = atan(uv.x, uv.y) * 0.159 + 0.5;
    rUV.y = length(uv) * 0.6;

    return rUV * 2.0;
}

// 3D SDFs from https://iquilezles.org/articles/distfunctions
float sdBox(vec3 p, vec3 s) {
    vec3 q = abs(p) - s;
    return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

float sdVerticalCapsule(vec3 p, float h, float r)
{
  p.y -= clamp(p.y, 0.0, h);
  return length(p) - r;
}

float sdCylinder(vec3 p, vec3 a, vec3 b, float r)
{
    vec3  ba = b - a;
    vec3  pa = p - a;
    float baba = dot(ba,ba);
    float paba = dot(pa,ba);
    float x = length(pa*baba-ba*paba) - r*baba;
    float y = abs(paba-baba*0.5)-baba*0.5;
    float x2 = x*x;
    float y2 = y*y*baba;

    float d = (max(x,y)<0.0)?-min(x2,y2):(((x>0.0)?x2:0.0)+((y>0.0)?y2:0.0));

    return sign(d)*sqrt(abs(d))/baba;
}

float surfaceMin(float a, float b)
{
    return (a<b) ? a : b;
}

vec2 getDist(vec3 p) {

    mat3 rot = rotateY(-iTime);
    vec3 diskPosRot = p*rot; // position with Y rotation

    vec2 radUV = radialUV(diskPosRot.xz*0.5) * vec2(0.0001, 1.0);
    vec3 diskSurfTex = vec3(0.0, texture(iChannel1, radUV).x*0.01 + texture(iChannel1, diskPosRot.xz*0.5).x*0.002 + 0.01, 0.0);
    diskSurfTex = radUV.y > 0.52 && radUV.y < 1.15 ? diskSurfTex : vec3(0.0, 0.01, 0.0);

    vec2 disk = vec2(sdCylinder(
        diskPosRot,
        diskSurfTex, // disk surface a
        -diskSurfTex, // disk surface b
        2.0), // disk radius
        radUV.y > 0.03 && radUV.y < 0.43 ? 0.0 : 1.0 // Material ID
    );

    float hole = sdCylinder(
        diskPosRot,
        vec3(0,1,0),
        vec3(0,-1,0),
        0.04 // hole radius
    );

    disk.x = max(disk.x, -hole);

    return disk;

}

vec3 getNormal(vec3 p) {
    float d = getDist(p).x;
    vec2 e = vec2(0.01, 0);

    vec3 n = d - vec3(
        getDist(p-e.xyy).x,
        getDist(p-e.yxy).x,
        getDist(p-e.yyx).x);

    return normalize(n);
}

vec2 rayMarch(vec3 ro, vec3 rd) {

    float dO = 0.0;
    vec2 distCol;
    vec3 p;

    for (int i=0; i<MAX_STEPS; i++){
        p = ro + rd*dO;
        distCol = getDist(p);
        float dS = distCol.x;
        dO += dS;
        if (dO>MAX_DIST || abs(dS)<SURFACE_DIST) break;
    }

    return vec2(dO, distCol.y);
}

vec3 getLight(vec3 p, vec3 n, vec3 c, vec3 lp) {

    vec3 l = normalize(lp - p);
    float diff = dot(n, l);
    return clamp(diff * c, 0.0, 1.0);
}

vec3 getSpecular(vec3 p, vec3 n, vec3 c, vec3 lp, vec3 ro, float sp) {

    vec3 l = normalize(lp - p);
    vec3 h = normalize(l + normalize(ro - p));

    return c * pow(max(0.0, dot(n, h)), sp);
}

void getMat(in vec3 p, in float id, inout vec3 col, inout float sp, inout float refl) {

    mat3 rot = rotateY(-iTime);
    vec3 diskPosRot = p*rot; // position with Y rotation

    int i = int(id);
    switch(i) {
        case 0: // Label
            col = pow(texture(iChannel2, diskPosRot.xz*vec2(0.35, 0.65) + vec2(0.5)).xyz, vec3(2.2));
            sp = 2.0;
            refl = 0.01;
            break;
        case 1: // Disk
            col = vec3(0);
            sp = 4.0;
            refl = 1.0;
            break;
    }

}

// Mouse rotation from the Art of Code https://www.shadertoy.com/view/sdsXWr
vec3 getRayDir(vec2 uv, vec3 p, vec3 l, float z) {
    vec3 f = normalize(l-p),
        r = normalize(cross(vec3(0,1,0), f)),
        u = cross(f,r),
        c = f*z,
        i = c + uv.x*r + uv.y*u,
        d = normalize(i);
    return d;
}

mat2 mouseRot(float a) {
    float s=sin(a), c=cos(a);
    return mat2(c, -s, s, c);
}

#ifdef AA
void mainImageRaw(out vec4 fragColor, in vec2 fragCoord)
#else
void mainImage(out vec4 fragColor, in vec2 fragCoord)
#endif
{

    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;

    //ray origin
    vec2 m = iMouse.xy/iResolution.xy - 0.5;
    vec3 ro = vec3(0, 4, -2);
    if (iMouse.z > 0.0) {
        ro.yz *= mouseRot(-m.y * 1.3 - 0.2);
        ro.xz *= mouseRot(-m.x*3.14159);
        ro.y = max(ro.y, 1.0);
    }
    // Ray direction
    vec3 rd = getRayDir(uv, ro, vec3(0, iMouse.z > 0.0 ? -(1.0 - iMouse.y/iResolution.y) : -1.0, 0), 1.0);

    // Raymarch and get values
    vec2 rs = rayMarch(ro, rd);
    vec3 p = (ro + rd * rs.x);
    vec3 n = getNormal(p);

    // Light position
    vec3 lp = vec3(1.0, 3.5, -1.0);

    // Get materials
    vec3 col = vec3(0);
    float sp = 0.0;
    float refl = 0.0;
    getMat(p, rs.y, col, sp, refl);

    // Diffuse lighting
    vec3 diff = getLight(p, n, vec3(1), lp);

    // Specular
    vec3 spec = getSpecular(p, n, vec3(1), lp, ro, sp);

    // Reflection
    float fresnel = pow(1.0-dot(n,-rd), 2.0);
    vec3 reflTex = refl * pow(texture(iChannel0, reflect(rd, n)).xyz, vec3(2.2)) * max(fresnel, 0.01);

    // Combine
    vec3 color = clamp(clamp(diff*spec, 0.1, 1.0) * (col + reflTex), 0.0, 1.0);

    // Material debug
    //color = vec3(rs.x*0.1); // Dist
    //color = vec3(diff); // Diffuse lighting
    //color = vec3(rs.y*0.5); // Material ID
    //color = col; // Color
    //color = vec3(spec); // Specular
    //color = reflTex; // Reflection

    // Buffer Debug
    //fragColor = texture(iChannel2, fragCoord / iResolution.xy);

    // Gamma
    color = pow(color, vec3(0.4545));

    // Background
    vec3 background = texture(iChannel0, vec3(uv.x, uv.y, 1.0), 1.0).xyz;
    //vec3 background = vec3(0);
    color = rs.x < MAX_DIST ? color : background;

    fragColor = vec4(color, 1.0);

}

#ifdef AA
// Antialiasing "module" by FabriceNeyret2 https://www.shadertoy.com/view/WlfyW8
void mainImage(out vec4 O, vec2 U) {
    vec4 T;  
    O = vec4(0);                                          
    for (int k=0; k<AA*AA; k++, O+=T) {              
        mainImageRaw(T, U + 0.33 * vec2(k%AA - AA/2, k/AA - AA/2));
    }
    O /= float(AA*AA);
}
#endif
